import { profile } from "@/content/profile";

// Generated by route handlers whose paths end in .png: GitHub Pages picks the
// Content-Type from the file extension, so extensionless metadata routes
// (opengraph-image, icon) would be served as application/octet-stream.
export const OG_IMAGE = {
  url: "/og.png",
  width: 1200,
  height: 630,
  alt: `${profile.name} — ${profile.roles}`,
};

export const ICON = { url: "/icon.png", size: 64 };
export const APPLE_ICON = { url: "/apple-icon.png", size: 180 };
